"use strict";
const pocketAnimeCards=[
 {id:'naruto-card',title:'火影忍者',from:2002,theme:'忍道与伙伴',image:'images/anime/naruto.jpg',source:'https://naruto-official.com/anime/naruto1',prompt:'如果只能带一个伙伴去完成任务，你会怎样分工？'},
 {id:'onepiece-card',title:'航海王',from:1999,theme:'大海与约定',image:'images/anime/onepiece.jpg',source:'https://one-piece.com/anime/index.html',prompt:'在不知道下一座岛的情况下，你会先准备什么？'},
 {id:'conan-card',title:'名侦探柯南',from:1996,theme:'证据与推理',source:'https://www.ytv.co.jp/conan/',prompt:'一个人说的时间不对，先认定撒谎还是再找一份记录？'},
 {id:'digimon-card',title:'数码宝贝大冒险',from:1999,theme:'搭档与勇气',source:'https://lineup.toei-anim.co.jp/ja/tv/dejimon/story/',prompt:'勇气一定是冲在前面吗？等待同伴也算不算勇敢？'},
 {id:'bleach-card',title:'死神 BLEACH',from:2004,fromDate:'2004-10-05',theme:'责任与日常',image:'images/anime/bleach.jpg',source:'https://bleach-anime.com/',prompt:'突然得到力量，你第一件想保护的事情是什么？'},
 {id:'slamdunk-card',title:'灌篮高手',from:1993,fromDate:'1993-10-16',theme:'球场与同伴',source:'https://lineup.toei-anim.co.jp/ja/tv/movie_slumdunk/story/',prompt:'你想把哪一句鼓励，留给今天还不敢上场的同学？'},
 {id:'dragon-card',title:'龙珠',from:1986,theme:'出发与冒险',source:'https://lineup.toei-anim.co.jp/ja/tv/dragon/',prompt:'为一个愿望踏上旅途，你会把什么放进背包？'},
 ...cartoonShelf.map(c=>({id:c.id+'-card',title:c.title,from:c.from,theme:'放学后的那一集',source:c.url,watch:c.id,prompt:'不说后来的结局，写一句你当时最想对主角说的话。'}))
];
let animeCard='',animeCollection=[],animeNotes={};
try{const p=JSON.parse(localStorage.getItem('olddays-pocket-anime')||'{}');animeCollection=pocketAnimeCards.filter(c=>p.collection?.includes(c.id)).map(c=>c.id);for(const c of pocketAnimeCards)if(typeof p.notes?.[c.id]==='string')animeNotes[c.id]=p.notes[c.id].slice(0,300);}catch{}
function savePocketAnime(){try{localStorage.setItem('olddays-pocket-anime',JSON.stringify({collection:animeCollection,notes:animeNotes}));}catch{}}
function pocketAnimeAvailable(c){return c.from<=Number(year())&&(!c.fromDate||c.fromDate<=date);}
function animePocketMarkup(){const available=pocketAnimeCards.filter(pocketAnimeAvailable),c=available.find(c=>c.id===animeCard);return `<section class="pocket-anime"><header><small>AFTER SCHOOL / 放学动漫社</small><h2>再聊一集，就回家。</h2><p>${date} · ${available.length}份年代收藏卡 · 我的收藏 ${animeCollection.filter(id=>available.some(c=>c.id===id)).length}</p></header>${campus.solved?`<aside class="campus-letter"><b>陈默的新留言</b><p>手机收到了，谢谢你没信传言。下次把耳机分你一半。${Object.values(animeNotes).some(Boolean)?'你留在动漫社的那句话，我也看到了。':'动漫社那本留言册，还给你留了一页。'}</p></aside>`:''}${c?`<article class="anime-card-detail">${animeCardArt(c)}<h2>${escapeHTML(c.title)}</h2><small>${c.from} / ${c.theme}</small><p>${c.prompt}</p><button data-anime-collect="${c.id}">${animeCollection.includes(c.id)?'✓ 已收藏这张卡':'☆ 收进我的收藏册'}</button><form data-pocket-anime-note><label>课桌上的追番留言<textarea name="note" maxlength="300" aria-label="动漫社留言">${escapeHTML(animeNotes[c.id]||'')}</textarea></label><button>留下这句回忆</button></form>${animeNotes[c.id]?`<p class="anime-local-note">你的留言：${escapeHTML(animeNotes[c.id])}</p>`:''}<a href="${c.source}" target="_blank" rel="noopener noreferrer">${c.watch?'打开已有正版片源':'作品官方资料'} ›</a><p>外站可能有最新剧情或地区限制；本卡为本站原创讨论，不提供盗版全集下载。</p><button data-anime-card-back>‹ 返回收藏卡册</button></article>`:`<div class="pocket-anime-grid">${available.map(c=>`<button data-anime-card="${c.id}">${animeCardArt(c)}<b>${escapeHTML(c.title)}</b><small>${c.theme}</small><em>${animeCollection.includes(c.id)?'已收藏 ✓':'翻开收藏卡 ›'}</em></button>`).join('')}</div><details><summary>打开现有正版放映目录</summary>${cartoonMarkup()}</details>`}<p>收藏和留言仅保存在本机。这里的收藏卡不是官方授权周边，不消耗话费。</p></section>`;}
function animeCardArt(c){return c.image?`<img src="${c.image}" alt="${escapeHTML(c.title)}海报资料图" loading="lazy">`:`<div class="anime-type-cover"><small>AFTER SCHOOL / ${c.from}</small><b>${escapeHTML(c.title)}</b><i>课桌上的回忆</i></div>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-anime-card],[data-anime-card-back],[data-anime-collect]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-anime-card-back'))animeCard='';else{const id=b.dataset.animeCard||b.dataset.animeCollect;if(!pocketAnimeCards.some(c=>c.id===id&&pocketAnimeAvailable(c)))return;if(b.dataset.animeCollect){if(!animeCollection.includes(id))animeCollection.push(id);savePocketAnime();}else animeCard=id;}refreshPhone();});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-pocket-anime-note]')||!pocketAnimeCards.some(c=>c.id===animeCard&&pocketAnimeAvailable(c)))return;e.preventDefault();animeNotes[animeCard]=String(new FormData(e.target).get('note')||'').trim().slice(0,300);savePocketAnime();refreshPhone();toast('这句回忆已经夹进收藏册');});
